                            /** @description Metrics recorded but not shown as numbers (weight shown as trend) */
                            withheld_metrics: ("weight" | "body_fat" | "waist" | "hips" | "chest" | "arm" | "thigh" | "neck" | "calf" | "arm_left" | "arm_right" | "thigh_left" | "thigh_right")[];
