                        /** @enum {string} */
                        kind: "execution" | "training_log" | "pr" | "injury" | "review" | "note" | "check_in" | "body" | "wellness" | "craving" | "device_activity";
                        /** @description The message sent to the coach, for coach_reply_requested. */
